CREATE TABLE IF NOT EXISTS "oauth_clients" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_id" VARCHAR(128) NOT NULL,
  "client_name" VARCHAR(200) NOT NULL,
  "description" TEXT NULL,
  "homepage_url" VARCHAR(500) DEFAULT NULL NULL,
  "redirect_uris" JSONB NOT NULL,
  "allowed_scopes" JSONB NOT NULL,
  "public_client" SMALLINT DEFAULT 1 NOT NULL,
  "require_pkce" SMALLINT DEFAULT 1 NOT NULL,
  "client_secret" VARCHAR(256) DEFAULT NULL NULL,
  "icon_filename" VARCHAR(200) DEFAULT NULL NULL,
  "vip_days_balance" INTEGER DEFAULT 0 NOT NULL,
  "is_active" SMALLINT DEFAULT 1 NOT NULL,
  "created_at" BIGINT NOT NULL,
  "updated_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "uq_oauth_clients_client_id" ON "oauth_clients" ("client_id");

CREATE INDEX IF NOT EXISTS "idx_client_id" ON "oauth_clients" ("client_id");

CREATE INDEX IF NOT EXISTS "idx_is_active" ON "oauth_clients" ("is_active");

CREATE TABLE IF NOT EXISTS "oauth_app_stats" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_id" VARCHAR(128) NOT NULL,
  "event_type" VARCHAR(32) NOT NULL,
  "user_id" VARCHAR(160) DEFAULT NULL NULL,
  "metadata" JSONB DEFAULT NULL NULL,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "idx_client_event" ON "oauth_app_stats" ("client_id", "event_type", "created_at");

CREATE INDEX IF NOT EXISTS "idx_created_at" ON "oauth_app_stats" ("created_at");

CREATE TABLE IF NOT EXISTS "oauth_vip_grants" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_id" VARCHAR(128) NOT NULL,
  "user_id" VARCHAR(160) NOT NULL,
  "user_type" VARCHAR(16) NOT NULL,
  "user_id_only" VARCHAR(128) NOT NULL,
  "days_granted" INTEGER NOT NULL,
  "access_key_value" VARCHAR(128) NOT NULL,
  "expires_at" TIMESTAMPTZ NOT NULL,
  "granted_at" BIGINT NOT NULL,
  "revoked_at" BIGINT DEFAULT NULL NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "idx_client_id" ON "oauth_vip_grants" ("client_id", "granted_at");

CREATE INDEX IF NOT EXISTS "idx_user_id" ON "oauth_vip_grants" ("user_id", "granted_at");

CREATE INDEX IF NOT EXISTS "idx_access_key" ON "oauth_vip_grants" ("access_key_value");

CREATE TABLE IF NOT EXISTS "oauth_authorization_codes" (
  "code_hash" CHAR(64) NOT NULL,
  "client_id" VARCHAR(191) NOT NULL,
  "user_id" VARCHAR(255) NOT NULL,
  "user_type" TEXT NOT NULL,
  "session_id" VARCHAR(255) DEFAULT NULL NULL,
  "scopes" TEXT NOT NULL,
  "redirect_uri" TEXT NOT NULL,
  "code_challenge" VARCHAR(255) DEFAULT NULL NULL,
  "code_challenge_method" VARCHAR(20) DEFAULT NULL NULL,
  "expires_at" TIMESTAMPTZ NOT NULL,
  "used_at" TIMESTAMPTZ DEFAULT NULL NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NULL,
  CONSTRAINT "oauth_authorization_codes_user_type_check" CHECK ("user_type" IN ('oauth', 'bip39')),
  PRIMARY KEY ("code_hash")
);

CREATE INDEX IF NOT EXISTS "idx_oauth_codes_client" ON "oauth_authorization_codes" ("client_id");

CREATE INDEX IF NOT EXISTS "idx_oauth_codes_user" ON "oauth_authorization_codes" ("user_id", "user_type");

CREATE INDEX IF NOT EXISTS "idx_oauth_codes_expiry" ON "oauth_authorization_codes" ("expires_at");

CREATE TABLE IF NOT EXISTS "oauth_authorization_requests" (
  "request_hash" CHAR(64) NOT NULL,
  "client_id" VARCHAR(191) NOT NULL,
  "redirect_uri" TEXT NOT NULL,
  "response_type" VARCHAR(20) DEFAULT 'code' NOT NULL,
  "scopes" TEXT NOT NULL,
  "state" TEXT NULL,
  "code_challenge" VARCHAR(255) DEFAULT NULL NULL,
  "code_challenge_method" VARCHAR(20) DEFAULT NULL NULL,
  "expires_at" TIMESTAMPTZ NOT NULL,
  "consumed_at" TIMESTAMPTZ DEFAULT NULL NULL,
  "decision" TEXT DEFAULT NULL NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NULL,
  "last_seen_at" TIMESTAMPTZ DEFAULT now() NULL,
  CONSTRAINT "oauth_authorization_requests_decision_check" CHECK ("decision" IN ('approved', 'rejected')),
  PRIMARY KEY ("request_hash")
);

CREATE INDEX IF NOT EXISTS "idx_oauth_requests_client" ON "oauth_authorization_requests" ("client_id");

CREATE INDEX IF NOT EXISTS "idx_oauth_requests_expiry" ON "oauth_authorization_requests" ("expires_at");

CREATE INDEX IF NOT EXISTS "idx_oauth_requests_consumed" ON "oauth_authorization_requests" ("consumed_at");

DROP TRIGGER IF EXISTS "oauth_authorization_requests_touch_last_seen_at" ON "oauth_authorization_requests";
CREATE TRIGGER "oauth_authorization_requests_touch_last_seen_at" BEFORE UPDATE ON "oauth_authorization_requests"
  FOR EACH ROW EXECUTE FUNCTION touch_updated_at("last_seen_at");

CREATE TABLE IF NOT EXISTS "oauth_access_tokens" (
  "token_hash" CHAR(64) NOT NULL,
  "client_id" VARCHAR(191) NOT NULL,
  "user_id" VARCHAR(255) NOT NULL,
  "user_type" TEXT NOT NULL,
  "session_id" VARCHAR(255) DEFAULT NULL NULL,
  "scopes" TEXT NOT NULL,
  "expires_at" TIMESTAMPTZ NOT NULL,
  "revoked_at" TIMESTAMPTZ DEFAULT NULL NULL,
