  "created_at" TIMESTAMPTZ DEFAULT now() NULL,
  "last_used_at" TIMESTAMPTZ DEFAULT now() NULL,
  CONSTRAINT "oauth_access_tokens_user_type_check" CHECK ("user_type" IN ('oauth', 'bip39')),
  PRIMARY KEY ("token_hash")
);

CREATE INDEX IF NOT EXISTS "idx_oauth_tokens_client" ON "oauth_access_tokens" ("client_id");

CREATE INDEX IF NOT EXISTS "idx_oauth_tokens_user" ON "oauth_access_tokens" ("user_id", "user_type");

